const clientes = $items('Read clientes (recordatorios)').map(i => i.json);
const logs = $items('Read logs (recordatorios)').map(i => i.json);
const now = new Date();

const types = [
  { name: 'RECORDATORIO_7D', diff: 7 },
  { name: 'RECORDATORIO_2D', diff: 2 },
  { name: 'VENCE_HOY', diff: 0 },
  { name: 'SEGUIMIENTO_3D', diff: -3 },
  { name: 'SEGUIMIENTO_7D', diff: -7 },
  { name: 'MOROSO_14D', diff: -14 }
];

const out = [];
for (const c of clientes) {
  if (c.estado !== 'ACTIVO' || c.consentimiento_mensajes !== 'SI') continue;
  const venc = c.proximo_vencimiento ? new Date(c.proximo_vencimiento) : null;
  if (!venc) continue;
  const diffDays = Math.floor((venc - now) / (1000 * 60 * 60 * 24));
  const match = types.find(t => diffDays === t.diff);
  if (!match) continue;

  const messageKey = `${c.cliente_id}_${match.name}_${c.proximo_vencimiento}`;
  const already = logs.find(l => l.message_key === messageKey);
  if (already) continue;

  out.push({
    json: {
      cliente: c,
      tipo_mensaje: match.name,
      message_key: messageKey,
      texto: `Hola ${c.nombre}, recordatorio: tu pago vence el ${c.proximo_vencimiento}. Si ya pagaste, ignora este mensaje.`
    }
  });
}

return out;

const clientes = items.map(i => i.json).filter(c => c.estado === 'ACTIVO');
const now = new Date();
let porVencer = 0;
let venceHoy = 0;
let vencidos1a7 = 0;
let morosos = 0;
let montoEsperado = 0;

for (const c of clientes) {
  const venc = c.proximo_vencimiento ? new Date(c.proximo_vencimiento) : null;
  if (!venc) continue;
  const diff = Math.floor((venc - now) / (1000 * 60 * 60 * 24));
  if (diff >= 0 && diff <= 2) porVencer += 1;
  if (diff === 0) venceHoy += 1;
  if (diff < 0 && diff >= -7) vencidos1a7 += 1;
  if (diff <= -8) morosos += 1;
  montoEsperado += Number(c.monto_mensual || 0);
}

const texto = `Reporte: Activos ${clientes.length}. Por vencer (0-2): ${porVencer}. Vence hoy: ${venceHoy}. Vencidos 1-7: ${vencidos1a7}. Morosos 8+: ${morosos}. Monto esperado: ${montoEsperado}.`;
return [{ json: { texto } }];
